}

function formatJiraMention(notifierId) {
    if (!notifierId) {
        return '';
    }
    var id = String(notifierId);
    if (id.indexOf('~') !== -1) {
        return '[' + id + ']';
    }
    return '[~accountid:' + id + ']';
}

